import{_ as e,o,c as i,ag as t}from"./chunks/framework.DXGyWiRo.js";const P=JSON.parse('{"title":"使用","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/use.md","filePath":"zh/guide/use.md","lastUpdated":1789862141000}'),l={name:"zh/guide/use.md"};function r(d,a,c,s,n,p){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h1><p>EasyYapi 支持以下使用方法：</p><h2 id="方式一-快捷键导出" tabindex="-1">方式一：快捷键导出 <a class="header-anchor" href="#方式一-快捷键导出" aria-label="Permalink to &quot;方式一：快捷键导出&quot;">​</a></h2><ol><li>打开项目中包含 API 的文件，或者在 IDEA 左边项目文件区域选择文件或文件夹</li><li>使用快捷键 <code>Alt + Shift + E</code> (Windows/Linux) 或 <code>Ctrl + E</code> (macOS)</li><li>选择要导出的 API</li><li>选择导出渠道：<code>YApi</code> / <code>Markdown</code> / <code>Postman</code></li><li>点击 ✔ 按钮或按回车键完成导出</li></ol><h2 id="方式二-右键导出" tabindex="-1">方式二：右键导出 <a class="header-anchor" href="#方式二-右键导出" aria-label="Permalink to &quot;方式二：右键导出&quot;">​</a></h2><ol><li>打开项目中包含 API 的文件，或者在 IDEA 左边项目文件区域选择文件或文件夹</li><li>鼠标右键点击文件内容或文件夹</li><li>选择 <code>ExportYapi</code> / <code>ExportPostman</code> / <code>ExportMarkdown</code> 导出该文件或文件夹中所有的 API</li></ol><h2 id="方式三-调用-api" tabindex="-1">方式三：调用 API <a class="header-anchor" href="#方式三-调用-api" aria-label="Permalink to &quot;方式三：调用 API&quot;">​</a></h2><ol><li>打开项目中包含 API 的文件</li><li>右键文件内容选择 <code>Call</code></li><li>在 IDE 中直接发起 API 请求</li></ol><p>详见 <a href="./call">Call API</a>。</p><h2 id="仅导出选中的方法" tabindex="-1">仅导出选中的方法 <a class="header-anchor" href="#仅导出选中的方法" aria-label="Permalink to &quot;仅导出选中的方法&quot;">​</a></h2><p>自 v3.2.0 起，EasyYapi 在导出时会尊重方法级选择。在触发导出之前，在编辑器中选中一个或多个方法（通过光标定位或拖选覆盖方法的文本范围）——只会导出源方法匹配（或覆盖）所选方法的端点，而不是包含类中的所有端点。</p><p>这对所有导出渠道均生效（YApi、Postman、Markdown、cURL、HttpClient、Hoppscotch、OpenAPI、ApiPost）。若未选中任何方法，则仍按以往行为导出整个包含类。</p><h2 id="复制-api-地址" tabindex="-1">复制 API 地址 <a class="header-anchor" href="#复制-api-地址" aria-label="Permalink to &quot;复制 API 地址&quot;">​</a></h2><ol><li>在编辑器或 Project 视图中选中一个或多个方法、一个类，或若干文件/文件夹</li><li>右键选择 <strong>EasyYapi</strong> &gt; <strong>Copy API URL</strong></li><li>所选范围内每个端点的地址会逐条复制到剪贴板，每行一条，格式为 <code>METHOD /path</code></li></ol><p>与 API Explorer 中只复制路径的 <strong>Copy Path</strong> 不同，<strong>Copy API URL</strong> 会带上 HTTP 方法——这样 <code>GET /user/{id}</code> 与 <code>PUT /user/{id}</code> 才能区分开。可以在 <strong>Features</strong> 中关闭（<code>Copy API URL</code>）。</p>',15)])])}const u=e(l,[["render",r]]);export{P as __pageData,u as default};
